'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

const COOKIE_NAME = 'notifications_enabled'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()
  const current = cookieStore.get(COOKIE_NAME)?.value === 'on'
  const next = !current

  cookieStore.set(COOKIE_NAME, next ? 'on' : 'off', {
    path: '/',
    maxAge: 60 * 60 * 24 * 365,
  })

  refresh()
}

